/** MIT; original A051 own dimensional/photo construction,no importedCAD. */
import * as THREE from 'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{hole,solid,ring,pcbContour}from'./geometry.js';import{spec}from'./dimensions.js';import{addStickers}from'./stickers.js';
export function buildM5Bit(host){const frame=new THREE.Group();frame.name='M5Bit complete originalA051 assembly';host.body.add(frame);const black=materials.plastic(0x1b2020,{roughness:.83}),metal=materials.metal(0xb9b9aa,{roughness:.4}),gold=materials.metal(0xb9a462,{roughness:.4}),yellow=materials.plastic(0xd6b834,{roughness:.73}),red=materials.plastic(0xa72832,{roughness:.73}),blue=materials.plastic(spec.grove.color,{roughness:.7}),substrate=materials.plastic(0x202324,{roughness:.91});const box=(s,p,n,m=black,parent=frame)=>mesh(parent,new THREE.BoxGeometry(...s),m,p,'M5Bit '+n);
 const ioSites=[],auxSites=[];for(let col=0;col<15;col++)for(let row=0;row<3;row++)ioSites.push({x:spec.io.firstX+col*2.54,y:-4-row*2.54,col,row});for(let col=0;col<2;col++)for(let row=0;row<4;row++)auxSites.push({x:22.1+col*5.08,y:-1.46-row*2.54,col,row});const groveSites=[-3,-1,1,3].map(t=>({x:-22.1,y:-5.4-t})),locators=[[-12.8,7.8],[12.8,7.8]];
 const shape=pcbContour();for(const p of[...ioSites,...auxSites,...groveSites])hole(shape,p.x,p.y,.44);for(const[x,y]of locators)hole(shape,x,y,.52);const pcb=solid(frame,shape,1,[0,0,0],substrate,'M5Bit actualPCB with57real lead drills andtwo locator bores');pcb.userData={role:'physical-pcb',inferred:true};const lands=[],barrels=[];for(const p of[...ioSites,...auxSites,...groveSites]){barrels.push(ring(frame,p.x,p.y,.44,.38,0,1,metal,'M5Bit actual plated lead retention barrel'));for(const z of[-.05,1])lands.push(ring(frame,p.x,p.y,.71,.38,z,.05,metal,'M5Bit throughhole solder land'));}
 const io={sites:ioSites,pins:[],insulators:[]},aux={sites:auxSites,pins:[],insulators:[]};for(const[group,sites]of[[io,ioSites],[aux,auxSites]])for(const p of sites){const colour=group===aux?red:[yellow,red,black][p.row];group.insulators.push(box([2.3,2.3,2.4],[p.x,p.y,2.2],'actual retained '+(group===io?'3colourIO':'redaux')+' insulator',colour));group.pins.push(box([.5,.5,9.1],[p.x,p.y,3.95],'actual square male header '+(group===io?`IO${p.col}/${p.row}`:`aux${p.col}/${p.row}`),gold));}
 const edgeFrame=new THREE.Group();edgeFrame.name='M5Bit actual80contact edgecard receiver';frame.add(edgeFrame);const housing=[],edge={frame:edgeFrame,housing,contacts:[],returns:[],tails:[],pads:[],anchors:[],locators:[]};housing.push(box([57,7.5,3.3],[0,6.75,2.65],'edgecard solidlower carrier',black,edgeFrame));housing.push(box([57,7.5,2],[0,6.75,7.5],'edgecard solidupper carrier',black,edgeFrame));for(const sign of[-1,1])housing.push(box([2.3,7.5,2.2],[sign*27.35,6.75,5.4],'edgecard receivingendwall',black,edgeFrame));housing.push(box([52.4,.7,2.2],[0,3.35,5.4],'edgecard deep insertion stop',black,edgeFrame));
 for(let bank=0;bank<2;bank++)for(let col=0;col<40;col++){const x=(col-19.5)*1.27,z=bank===0?4.5:6.3,y=bank===0?2.8:1.6,tailX=x+(bank===0?-.29:.29);edge.contacts.push(box([.5,6.1,.2],[x,7.05,z],`edge bank${bank+1} col${col+1} opposed retainedspring`,gold,edgeFrame));edge.returns.push(box([.3,.3,z-1.1],[tailX,3.85,(z+1.1)/2],`edge bank${bank+1} col${col+1} fixedreturn`,metal,edgeFrame));edge.tails.push(box([.3,3.85-y,.16],[tailX,(3.85+y)/2,1.13],`edge bank${bank+1} col${col+1} actualSMTtail`,metal,edgeFrame));edge.pads.push(box([.62,.9,.05],[tailX,y,1.025],`edge bank${bank+1} col${col+1} actualSMTland`,metal,edgeFrame));}
 for(const[x,y]of locators)edge.locators.push(mesh(edgeFrame,new THREE.CylinderGeometry(.49,.49,1.4,24).rotateX(Math.PI/2),black,[x,y,.3],'M5Bit cardreceiver actual locator intoPCB'));for(const sign of[-1,1])edge.anchors.push(box([.8,1.8,.16],[sign*27.5,9.3,-.05],'edgecard retained solderanchor',metal,edgeFrame));
 const edgePort=host.add(new Port({id:'microbit',label:'Microbit physical edge-card receiver',connector:'m5.a051.microbit-edge',position:spec.edge.position,hitSize:[52.4,1,2.2],meta:{role:'visual-connector',physicalContacts:80,banks:2,columns:40,pitchMm:1.27,scope:'Actual80mechanicalcontacts only;not80signals,not BBC25pin netlist;no supplied Microbit board orUART/IO behavior'}}),frame);edge.port=edgePort;
 const ioPort=host.add(new Port({id:'io',label:'Actual3×15 maleIOheader',connector:'m5.a051.io-3x15',position:[0,-6.54,8.5],quaternion:portQuaternion('front'),hitSize:[37.86,1,7.38],meta:{role:'visual-connector',physicalContacts:45,printedColumns:spec.io.printedColumns,scope:'Actual3colour malecontact geometry only;noGPIOorrailrouting'}}),frame);io.port=ioPort;const auxPort=host.add(new Port({id:'aux',label:'Actual2×4 redauxheader',connector:'m5.a051.aux-2x4',position:[24.64,-5.27,8.5],quaternion:portQuaternion('front'),hitSize:[7.38,1,9.92],meta:{role:'visual-connector',physicalContacts:8,printedRows:['DA','CL','V','G'],scope:'Actual2redcolumns only;noelectricalnetlist inferred fromletters'}}),frame);aux.port=auxPort;
 const groveFrame=new THREE.Group();groveFrame.position.fromArray(spec.grove.position);groveFrame.quaternion.copy(FACE.left);groveFrame.name='M5Bit blue physicalGrove4P receiver';frame.add(groveFrame);const gbox=(s,p,n,m=blue)=>mesh(groveFrame,new THREE.BoxGeometry(...s),m,p,'M5Bit Grove '+n),grove={frame:groveFrame,walls:[],contacts:[],returns:[],tails:[]};for(const sign of[-1,1]){grove.walls.push(gbox([.65,5.2,6.85],[sign*4.675,0,-3.425],'sidewall'));grove.walls.push(gbox([.6,.45,1.4],[sign*3.8,2.375,-1.8],'retained latchshoulder'));}grove.floor=gbox([8.7,.65,6.85],[0,-2.275,-3.425],'floor');grove.back=gbox([8.7,4.55,.65],[0,.325,-6.525],'deep stop');grove.bridge=gbox([4.8,.45,2],[0,2.375,-5],'lockingbridge');for(let i=0;i<4;i++){const x=(i-1.5)*2;grove.contacts.push(gbox([.42,.42,4.6],[x,-.1,-3.85],'realcontact '+(i+1),metal));grove.returns.push(gbox([.42,3.0,.42],[x,-1.6,-6.4],'realbentreturn '+(i+1),metal));grove.tails.push(gbox([.42,1,.42],[x,-3.1,-6.4],'throughPCB soldertail '+(i+1),metal));}grove.port=host.add(new Port({id:'grove',label:'PORT.C actualfourcontactHY2.0',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('left'),hitSize:[10,1,5.2],meta:{role:'visual-connector',physicalContacts:4,scope:'Fourcontact mechanicalconnection only;noUART,power,voltage orsignalrouting'}}),frame);
 const back={regulator:null,capacitors:[],leads:[],pads:[]};back.regulator=box([6.1,3.5,1.6],[0,3.2,-1.0],'own visible fixedSOT223 package',black);for(const x of[-2.05,0,2.05]){back.leads.push(box([.7,1.4,.22],[x,5.3,-.11],'SOT223 actual upperretainedlead',metal));back.pads.push(box([.95,1.8,.06],[x,5.3,-.03],'SOT223 upper solderpad',metal));}back.leads.push(box([5.5,1.5,.22],[0,.8,-.11],'SOT223 actual lowertab',metal));back.pads.push(box([5.8,1.8,.06],[0,.8,-.03],'SOT223 actualtab solderpad',metal));for(const x of[-6.75,6.75]){back.capacitors.push(box([3.4,5.3,2.3],[x,3.1,-1.35],'own orange retainedcapacitor body',materials.plastic(0xb88235,{roughness:.79})));for(const y of[.1,6.1]){back.leads.push(box([3.1,.8,.22],[x,y,-.11],'capacitor actual metallizedfoot',metal));back.pads.push(box([3.6,1.0,.06],[x,y,-.03],'capacitor actual solderpad',metal));}}const frontPassives=[];for(const[x,y]of[[18.9,.5],[21.9,.5],[-10.4,.5]]){frontPassives.push(box([2.1,1,.5],[x,y,1.3],'own front fixedpassive',black));for(const sign of[-1,1])box([.45,1,.16],[x+sign*.9,y,1.08],'frontpassive soldertermination',metal);}
 host.m5BitAssembly={frame,pcb,lands,barrels,io,aux,edge,grove,back,frontPassives,locatorHoles:locators};host.unitStickers=addStickers(host,pcb);
}
